candidate_patch.patch:
--- baseline/grbl/gcode.c
+++ candidate/grbl/gcode.c
@@ -36,6 +36,7 @@
 parser_block_t gc_block;

 #define FAIL(status) return(status);
+#define VALUE_WORD_MASK(n) (UINT32_C(1) << (n))


 void gc_init() 
@@ -94,7 +95,7 @@

   // Initialize command and value words variables. Tracks words contained in this block.
   uint16_t command_words = 0; // G and M command words. Also used for modal group violations.
-  uint16_t value_words = 0; // Value words. 
+  uint32_t value_words = 0; // Value words. 

   /* -------------------------------------------------------------------------------------
      STEP 2: Import all g-code words in the block line. A g-code word is a letter followed by
@@ -375,13 +376,13 @@
         } 

         // NOTE: Variable 'word_bit' is always assigned, if the non-command letter is valid.
-        if (bit_istrue(value_words,bit(word_bit))) { FAIL(STATUS_GCODE_WORD_REPEATED); } // [Word repeated]
+        if (bit_istrue(value_words,VALUE_WORD_MASK(word_bit))) { FAIL(STATUS_GCODE_WORD_REPEATED); } // [Word repeated]
         // Check for invalid negative values for words F, N, P, T, and S.
         // NOTE: Negative value check is done here simply for code-efficiency.
-        if ( bit(word_bit) & (bit(WORD_F)|bit(WORD_N)|bit(WORD_P)|bit(WORD_T)|bit(WORD_S)) ) {
+        if ( VALUE_WORD_MASK(word_bit) & (VALUE_WORD_MASK(WORD_F)|VALUE_WORD_MASK(WORD_N)|VALUE_WORD_MASK(WORD_P)|VALUE_WORD_MASK(WORD_T)|VALUE_WORD_MASK(WORD_S)) ) {
           if (value < 0.0) { FAIL(STATUS_NEGATIVE_VALUE); } // [Word value cannot be negative]
         }
-        value_words |= bit(word_bit); // Flag to indicate parameter assigned.
+        value_words |= VALUE_WORD_MASK(word_bit); // Flag to indicate parameter assigned.

     }   
   } 
@@ -423,11 +424,11 @@
   }

   // Check for valid line number N value.
-  if (bit_istrue(value_words,bit(WORD_N))) {
+  if (bit_istrue(value_words,VALUE_WORD_MASK(WORD_N))) {
     // Line number value cannot be less than zero (done) or greater than max line number.
     if (gc_block.values.n > MAX_LINE_NUMBER) { FAIL(STATUS_GCODE_INVALID_LINE_NUMBER); } // [Exceeds max line number]
   }
-  // bit_false(value_words,bit(WORD_N)); // NOTE: Single-meaning value word. Set at end of error-checking.
+  // bit_false(value_words,VALUE_WORD_MASK(WORD_N)); // NOTE: Single-meaning value word. Set at end of error-checking.

   // Track for unused words at the end of error-checking.
   // NOTE: Single-meaning value words are removed all at once at the end of error-checking, because
@@ -444,7 +445,7 @@
     // NOTE: G38 can also operate in inverse time, but is undefined as an error. Missing F word check added here.
     if (axis_command == AXIS_COMMAND_MOTION_MODE) { 
       if ((gc_block.modal.motion != MOTION_MODE_NONE) || (gc_block.modal.motion != MOTION_MODE_SEEK)) {
-        if (bit_isfalse(value_words,bit(WORD_F))) { FAIL(STATUS_GCODE_UNDEFINED_FEED_RATE); } // [F word missing]
+        if (bit_isfalse(value_words,VALUE_WORD_MASK(WORD_F))) { FAIL(STATUS_GCODE_UNDEFINED_FEED_RATE); } // [F word missing]
       }
     }
     // NOTE: It seems redundant to check for an F word to be passed after switching from G94 to G93. We would
@@ -462,21 +463,21 @@
   } else { // = G94
     // - In units per mm mode: If F word passed, ensure value is in mm/min, otherwise push last state value.
     if (gc_state.modal.feed_rate == FEED_RATE_MODE_UNITS_PER_MIN) { // Last state is also G94
-      if (bit_istrue(value_words,bit(WORD_F))) {
+      if (bit_istrue(value_words,VALUE_WORD_MASK(WORD_F))) {
         if (gc_block.modal.units == UNITS_MODE_INCHES) { gc_block.values.f *= MM_PER_INCH; }
       } else {
         gc_block.values.f = gc_state.feed_rate; // Push last state feed rate
       }
     } // Else, switching to G94 from G93, so don't push last state feed rate. Its undefined or the passed F word value.
   } 
-  // bit_false(value_words,bit(WORD_F)); // NOTE: Single-meaning value word. Set at end of error-checking.
+  // bit_false(value_words,VALUE_WORD_MASK(WORD_F)); // NOTE: Single-meaning value word. Set at end of error-checking.

   // [4. Set spindle speed ]: S is negative (done.)
-  if (bit_isfalse(value_words,bit(WORD_S))) { gc_block.values.s = gc_state.spindle_speed; }
-  // bit_false(value_words,bit(WORD_S)); // NOTE: Single-meaning value word. Set at end of error-checking.
+  if (bit_isfalse(value_words,VALUE_WORD_MASK(WORD_S))) { gc_block.values.s = gc_state.spindle_speed; }
+  // bit_false(value_words,VALUE_WORD_MASK(WORD_S)); // NOTE: Single-meaning value word. Set at end of error-checking.

   // [5. Select tool ]: NOT SUPPORTED. Only tracks value. T is negative (done.) Not an integer. Greater than max tool value.
-  // bit_false(value_words,bit(WORD_T)); // NOTE: Single-meaning value word. Set at end of error-checking.
+  // bit_false(value_words,VALUE_WORD_MASK(WORD_T)); // NOTE: Single-meaning value word. Set at end of error-checking.

   // [6. Change tool ]: N/A
   // [7. Spindle control ]: N/A
@@ -485,8 +486,8 @@

   // [10. Dwell ]: P value missing. P is negative (done.) NOTE: See below.
   if (gc_block.non_modal_command == NON_MODAL_DWELL) {
-    if (bit_isfalse(value_words,bit(WORD_P))) { FAIL(STATUS_GCODE_VALUE_WORD_MISSING); } // [P word missing]
-    bit_false(value_words,bit(WORD_P));
+    if (bit_isfalse(value_words,VALUE_WORD_MASK(WORD_P))) { FAIL(STATUS_GCODE_VALUE_WORD_MISSING); } // [P word missing]
+    bit_false(value_words,VALUE_WORD_MASK(WORD_P));
   }

   // [11. Set active plane ]: N/A
@@ -562,15 +563,15 @@
       // [G10 L2 Errors]: R word NOT SUPPORTED. P value not 0 to nCoordSys(max 9). Axis words missing.
       // [G10 L20 Errors]: P must be 0 to nCoordSys(max 9). Axis words missing.
       if (!axis_words) { FAIL(STATUS_GCODE_NO_AXIS_WORDS) }; // [No axis words]
-      if (bit_isfalse(value_words,((1<<WORD_P)|(1<<WORD_L)))) { FAIL(STATUS_GCODE_VALUE_WORD_MISSING); } // [P/L word missing]
+      if (bit_isfalse(value_words,((VALUE_WORD_MASK(WORD_P))|(VALUE_WORD_MASK(WORD_L))))) { FAIL(STATUS_GCODE_VALUE_WORD_MISSING); } // [P/L word missing]
       coord_select = trunc(gc_block.values.p); // Convert p value to int.
       if (coord_select > N_COORDINATE_SYSTEM) { FAIL(STATUS_GCODE_UNSUPPORTED_COORD_SYS); } // [Greater than N sys]
       if (gc_block.values.l != 20) {
         if (gc_block.values.l == 2) {
-          if (bit_istrue(value_words,bit(WORD_R))) { FAIL(STATUS_GCODE_UNSUPPORTED_COMMAND); } // [G10 L2 R not supported]
+          if (bit_istrue(value_words,VALUE_WORD_MASK(WORD_R))) { FAIL(STATUS_GCODE_UNSUPPORTED_COMMAND); } // [G10 L2 R not supported]
         } else { FAIL(STATUS_GCODE_UNSUPPORTED_COMMAND); } // [Unsupported L]
       }
-      bit_false(value_words,(bit(WORD_L)|bit(WORD_P)));
+      bit_false(value_words,(VALUE_WORD_MASK(WORD_L)|VALUE_WORD_MASK(WORD_P)));

       // Determine coordinate system to change and try to load from EEPROM.
       if (coord_select > 0) { coord_select--; } // Adjust P1-P6 index to EEPROM coordinate data indexing.
@@ -712,8 +713,8 @@
           x = gc_block.values.xyz[axis_0]-gc_state.position[axis_0]; // Delta x between current position and target
           y = gc_block.values.xyz[axis_1]-gc_state.position[axis_1]; // Delta y between current position and target

-          if (value_words & bit(WORD_R)) { // Arc Radius Mode  
-            bit_false(value_words,bit(WORD_R));
+          if (value_words & VALUE_WORD_MASK(WORD_R)) { // Arc Radius Mode  
+            bit_false(value_words,VALUE_WORD_MASK(WORD_R));
             if (gc_check_same_position(gc_state.position, gc_block.values.xyz)) { FAIL(STATUS_GCODE_INVALID_TARGET); } // [Invalid target]

             // Convert radius value to proper units.
@@ -806,7 +807,7 @@

           } else { // Arc Center Format Offset Mode  
             if (!(ijk_words & (bit(axis_0)|bit(axis_1)))) { FAIL(STATUS_GCODE_NO_OFFSETS_IN_PLANE); } // [No offsets in plane]
-            bit_false(value_words,(bit(WORD_I)|bit(WORD_J)|bit(WORD_K)));  
+            bit_false(value_words,(VALUE_WORD_MASK(WORD_I)|VALUE_WORD_MASK(WORD_J)|VALUE_WORD_MASK(WORD_K)));  

             // Convert IJK values to proper units.
             if (gc_block.modal.units == UNITS_MODE_INCHES) {
@@ -848,8 +849,8 @@

   // [0. Non-specific error-checks]: Complete unused value words check, i.e. IJK used when in arc
   // radius mode, or axis words that aren't used in the block.  
-  bit_false(value_words,(bit(WORD_N)|bit(WORD_F)|bit(WORD_S)|bit(WORD_T))); // Remove single-meaning value words. 
-  if (axis_command) { bit_false(value_words,(bit(WORD_A)|bit(WORD_B)|bit(WORD_C)|bit(WORD_D)|bit(WORD_X)|bit(WORD_Y)|bit(WORD_Z))); } // Remove axis words. 
+  bit_false(value_words,(VALUE_WORD_MASK(WORD_N)|VALUE_WORD_MASK(WORD_F)|VALUE_WORD_MASK(WORD_S)|VALUE_WORD_MASK(WORD_T))); // Remove single-meaning value words. 
+  if (axis_command) { bit_false(value_words,(VALUE_WORD_MASK(WORD_A)|VALUE_WORD_MASK(WORD_B)|VALUE_WORD_MASK(WORD_C)|VALUE_WORD_MASK(WORD_D)|VALUE_WORD_MASK(WORD_X)|VALUE_WORD_MASK(WORD_Y)|VALUE_WORD_MASK(WORD_Z))); } // Remove axis words. 
   if (value_words) { FAIL(STATUS_GCODE_UNUSED_WORDS); } // [Unused words]
